/**
 * useUpgradeStore（Pinia）
 * 目标：版本升级/version页面在“路由切换/返回”后，不丢上传/升级进度与UI选择。
 *
 * 核心设计：
 * - cache：按设备(devid)缓存 UI 与文件态（name/raw/size/status/percent/task/upgradeStatus，
 *   以及 uploadFinished/upgradeFinished）。保留 File/Blob 引用（不做 JSON 拷贝）。
 * - uploaders：为每个设备常驻一个 VersionUpgrade 实例，避免切页被销毁导致任务中断。
 * - ui：右侧抽屉/当前选中项等页面 UI 状态。
 *
 * 对外能力：
 * - setUI / setFiles / setFlags / getSnapshot / getUploader：读取更新状态的工具。
 * - startUpload(...)：发起上传，实时回调进度/完成/错误；状态写入 cache。
 * - startUpgrade(...)：发起升级，实时回调进度/阶段成功/错误；状态写入 cache。
 *
 * 使用效果：
 * - 切换到其它页面再返回，仍能看到同一设备的上传/升级进度与状态；任务不中断。
 */

import { defineStore } from 'pinia'
import VersionUpgrade from '@/utils/version_upgrade.js'

export const useUpgradeStore = defineStore('upgrade', {
  state: () => ({
    // 每个设备持久在内存的 UI 状态（不会随路由卸载）
    cache: {
      // [devid]: { files: [{ name, raw(Blob), size, status, percent, task, upgradeStatus }], uploadFinished, upgradeFinished }
    },
    // 正在运行的上传/升级器实例，避免路由切换被销毁
    uploaders: {
      // [devid]: VersionUpgrade instance
    },
    ui: {
      showRight: false,
      selectedItemId: null,
      selectedDevDesp: ''
    }
  }),
  actions: {
    // 更新 UI 状态（部分字段覆盖）
    setUI(partial) {
      this.ui = { ...this.ui, ...partial }
    },

    ensureDev(devid) {
      if (!this.cache[devid])
        this.cache[devid] = {
          files: [],
          uploadFinished: false,
          upgradeFinished: false
        }
    },
    setFiles(devid, files) {
      this.ensureDev(devid)
      // 不做 JSON 深拷，保留 raw 的 Blob/File
      this.cache[devid].files = files.map((f) => ({ ...f }))
    },
    setFlags(devid, { uploadFinished, upgradeFinished }) {
      this.ensureDev(devid)
      if (uploadFinished !== undefined)
        this.cache[devid].uploadFinished = !!uploadFinished
      if (upgradeFinished !== undefined)
        this.cache[devid].upgradeFinished = !!upgradeFinished
    },
    getSnapshot(devid) {
      return (
        this.cache[devid] || {
          files: [],
          uploadFinished: false,
          upgradeFinished: false
        }
      )
    },
    getUploader(devid) {
      if (!this.uploaders[devid]) {
        this.uploaders[devid] = new VersionUpgrade()
      }
      return this.uploaders[devid]
    },

    // 开始上传
    startUpload({
      devid,
      devname,
      file,
      packageName,
      socketUrl,
      index,
      onPercent,
      onFinished,
      onError
    }) {
      const uploader = this.getUploader(devid)
      uploader.setSocketUrl(socketUrl)

      const f = {
        name: packageName,
        raw: file,
        size: `${(file.size / 1024 / 1024).toFixed(2)}MB`,
        status: 'uploading',
        percent: 0,
        task: 'upload'
      }
      this.setFiles(devid, [f])
      this.setFlags(devid, { uploadFinished: false })

      uploader.startUpload(file, {
        devid,
        devname,
        package_name: packageName,
        task: 'VERSION_UPLOAD_FILE',
        debug: true,
        index,
        onEventUploadPercent: (obj, data) => {
          const files = this.cache[devid]?.files || []
          if (files[0]) files[0].percent = data.percent || 0
          onPercent && onPercent(data.percent || 0)
        },
        onEventUploadFinished: () => {
          const files = this.cache[devid]?.files || []
          if (files[0]) files[0].status = 'success'
          this.setFlags(devid, { uploadFinished: true })
          onFinished && onFinished()
        },
        onEventErrorMessage: (obj, resp) => {
          const files = this.cache[devid]?.files || []
          if (files[0]) {
            files[0].status = 'error'
            files[0].task = 'upload'
          }
          onError && onError(resp)
        }
      })
    },

    // 开始升级
    startUpgrade({
      devid,
      devname,
      packageName,
      socketUrl,
      onProgress,
      onPartial,
      onFull,
      onError
    }) {
      const uploader = this.getUploader(devid)
      uploader.setSocketUrl(socketUrl)

      const files = this.cache[devid]?.files || []
      if (files[0]) {
        files[0].status = 'upgrading'
        files[0].task = 'upgrade'
        files[0].percent = 0
        files[0].upgradeStatus = ''
      }
      this.setFlags(devid, { upgradeFinished: false })

      uploader.startUpgrade({
        devid,
        devname,
        package_name: packageName,
        task: 'VERSION_UPGRAD_ING',
        debug: true,
        onEventUpgradeProgress: (obj, data) => {
          const f = this.cache[devid]?.files?.[0]
          if (f) {
            f.percent = Math.round(data.percent || 0)
            f.upgradeStatus = data.upgradeStatus || ''
          }
          onProgress && onProgress(data)
        },
        onUpgradePartialSuccess: () => {
          const f = this.cache[devid]?.files?.[0]
          if (f) f.status = 'success'
          this.setFlags(devid, { upgradeFinished: true })
          onPartial && onPartial()
        },
        onUpgradeFullSuccess: () => {
          const f = this.cache[devid]?.files?.[0]
          if (f) f.status = 'success'
          this.setFlags(devid, { upgradeFinished: true })
          onFull && onFull()
        },
        onEventErrorMessage: (obj, resp) => {
          const f = this.cache[devid]?.files?.[0]
          if (f) {
            f.status = 'error'
            f.task = 'upgrade'
            f.upgradeStatus = resp?.versionUpdateResponse?.upgradeStatus || ''
          }
          onError && onError(resp)
        }
      })
    }
  }
})
